// Minimalna atrapa "next/server" do testów middleware.ts poza Next.js
// (w repozytorium nie ma node_modules — instalacja odbywa się przy budowie
// na Railway). Odwzorowuje tylko to, czego używa middleware: NextRequest
// z nextUrl oraz NextResponse.next/json/redirect z res.cookies.set.
class NextRequest extends Request {
  constructor(input, init) {
    super(input, init);
    this.nextUrl = new URL(typeof input === "string" ? input : input.url);
  }
}
function withCookies(res) {
  res.cookies = {
    set(name, value, opts) {
      opts = opts || {};
      var parts = [name + "=" + encodeURIComponent(value)];
      if (opts.path) parts.push("Path=" + opts.path);
      if (typeof opts.maxAge === "number") parts.push("Max-Age=" + opts.maxAge);
      if (opts.httpOnly) parts.push("HttpOnly");
      if (opts.secure) parts.push("Secure");
      if (opts.sameSite) parts.push("SameSite=" + String(opts.sameSite).replace(/^./, (c) => c.toUpperCase()));
      res.headers.append("set-cookie", parts.join("; "));
    }
  };
  return res;
}
class NextResponse extends Response {
  static next() {
    return withCookies(new NextResponse(null, { status: 200 }));
  }
  static json(body, init) {
    var res = new NextResponse(JSON.stringify(body), Object.assign({ status: 200 }, init || {}));
    res.headers.set("content-type", "application/json");
    return withCookies(res);
  }
  static redirect(url, init) {
    var status = typeof init === "number" ? init : (init && init.status) || 307;
    var res = new NextResponse(null, { status: status });
    res.headers.set("location", String(url));
    return withCookies(res);
  }
}
module.exports = { NextRequest, NextResponse };
